use std::path::{Path, PathBuf};

/// Normalize a path for use in generated code and log messages.
///
/// `fs::canonicalize` returns a *verbatim* path on Windows, e.g.
/// `\\?\C:\project\static`, which is not what users expect to see and is
/// awkward to embed in the source file that is generated by the build script.
/// Strip the verbatim prefix here; the remaining path still points to the
/// same file.
#[cfg_attr(not(windows), allow(unused_variables))]
pub(crate) fn normalize_path(path: &Path) -> PathBuf {
    #[cfg(windows)]
    {
        if let Some(path) = path.to_str() {
            // verbatim UNC paths: `\\?\UNC\server\share` -> `\\server\share`
            if let Some(rest) = path.strip_prefix(VERBATIM_UNC_PREFIX) {
                return PathBuf::from(format!(r"\\{rest}"));
            }

            // verbatim disk / other paths: `\\?\C:\dir` -> `C:\dir`
            if let Some(rest) = path.strip_prefix(VERBATIM_PREFIX) {
                return PathBuf::from(rest);
            }
        }
    }

    path.to_owned()
}

#[cfg(windows)]
const VERBATIM_PREFIX: &str = r"\\?\";

#[cfg(windows)]
const VERBATIM_UNC_PREFIX: &str = r"\\?\UNC\";

#[cfg(test)]
mod tests {
    use super::normalize_path;
    use std::path::{Path, PathBuf};

    #[test]
    fn plain_paths_are_unchanged() {
        assert_eq!(
            normalize_path(Path::new("some/relative/file.css")),
            PathBuf::from("some/relative/file.css")
        );
    }

    #[cfg(windows)]
    #[test]
    fn verbatim_disk_prefix_is_stripped() {
        assert_eq!(
            normalize_path(Path::new(r"\\?\C:\project\static")),
            PathBuf::from(r"C:\project\static")
        );
    }

    #[cfg(windows)]
    #[test]
    fn verbatim_unc_prefix_is_stripped() {
        assert_eq!(
            normalize_path(Path::new(r"\\?\UNC\server\share\static")),
            PathBuf::from(r"\\server\share\static")
        );
    }

    #[cfg(windows)]
    #[test]
    fn other_prefixes_are_unchanged() {
        // a device path (`\\.\`) and a plain UNC path are not verbatim paths
        assert_eq!(
            normalize_path(Path::new(r"\\.\C:\project")),
            PathBuf::from(r"\\.\C:\project")
        );
        assert_eq!(
            normalize_path(Path::new(r"\\server\share\static")),
            PathBuf::from(r"\\server\share\static")
        );
    }

    #[test]
    fn normalized_path_points_to_the_same_file() {
        let current_dir = std::env::current_dir().expect("current dir");
        let canonical = fs_err::canonicalize(&current_dir).expect("canonicalize current dir");

        let normalized = normalize_path(&canonical);

        assert_eq!(
            fs_err::canonicalize(&normalized).expect("recanonicalize"),
            canonical
        );
        assert!(!normalized.to_string_lossy().starts_with(r"\\?\"));
    }
}
